strings.esMX = strings.esES
strings.ptPT = strings.ptBR

local loc = GetLocale and GetLocale() or "enUS"
local active = strings[loc] or {}

-- T("English text") returns the text in the client's language.
function ns.T(s) return active[s] or s end
